#include <algorithm>

struct RECT { long left, top, right, bottom; };
struct Frame { int border; int caption; int menu; };

RECT adjustWindowRect(RECT client, Frame f)
{
    return { client.left - f.border, client.top - f.border - f.caption - f.menu, client.right + f.border, client.bottom + f.border };
}

namespace
{
    long floorDiv2(long v) { return v >= 0 ? v / 2 : -((-v + 1) / 2); }
}

RECT centredIn(RECT work, int width, int height)
{
    const long x{ work.left + floorDiv2((work.right - work.left) - width) };
    const long y{ work.top + floorDiv2((work.bottom - work.top) - height) };
    return { x, y, x + width, y + height };
}

RECT keepOnScreen(RECT w, RECT work)
{
    long width{ std::min(w.right - w.left, work.right - work.left) };
    long height{ std::min(w.bottom - w.top, work.bottom - work.top) };
    long x{ std::clamp(w.left, work.left, work.right - width) };
    long y{ std::clamp(w.top, work.top, work.bottom - height) };
    return { x, y, x + width, y + height };
}

unitTests:
bool same(RECT r, long l, long t, long rr, long b) { return r.left == l && r.top == t && r.right == rr && r.bottom == b; }
TEST("outer size") {
    CHECK(same(adjustWindowRect({ 0, 0, 800, 500 }, { 8, 31, 0 }), -8, -39, 808, 508));
    CHECK(same(adjustWindowRect({ 100, 100, 300, 200 }, { 1, 0, 20 }), 99, 79, 301, 201));
}
TEST("centred") { CHECK(same(centredIn({ 0, 0, 1920, 1040 }, 816, 539), 552, 250, 1368, 789)); CHECK(same(centredIn({ -1280, 0, 0, 1024 }, 100, 100), -690, 462, -590, 562)); CHECK(same(centredIn({ 0, 0, 100, 100 }, 201, 50), -51, 25, 150, 75)); }
TEST("kept on screen") {
    const RECT work{ 0, 0, 1920, 1040 };
    CHECK(same(keepOnScreen({ 1800, 900, 2200, 1200 }, work), 1520, 740, 1920, 1040));
    CHECK(same(keepOnScreen({ -50, 10, 350, 310 }, work), 0, 10, 400, 310));
    CHECK(same(keepOnScreen({ 100, 100, 2500, 300 }, work), 0, 100, 1920, 300));
    CHECK(same(keepOnScreen({ 10, 20, 110, 120 }, work), 10, 20, 110, 120));
}

